package ipfs

import (
	"bytes"
	"context"
	"encoding/binary"
	"fmt"
	"io"
	"testing"
)

// testReader yields n deterministic pseudo-random bytes (xorshift64, fixed
// seed), so a shorter stream is a prefix of a longer one and golden vectors
// can be regenerated by piping the same bytes into Kubo.
type testReader struct {
	x    uint64
	left int64
	buf  [8]byte
	off  int
}

func newTestReader(n int64) *testReader {
	return &testReader{x: 0x9e3779b97f4a7c15, left: n, off: 8}
}

func (r *testReader) Read(p []byte) (int, error) {
	if r.left == 0 {
		return 0, io.EOF
	}
	if int64(len(p)) > r.left {
		p = p[:r.left]
	}
	n := 0
	for n < len(p) {
		if r.off == 8 {
			r.x ^= r.x << 13
			r.x ^= r.x >> 7
			r.x ^= r.x << 17
			binary.LittleEndian.PutUint64(r.buf[:], r.x)
			r.off = 0
		}
		k := copy(p[n:], r.buf[r.off:])
		r.off += k
		n += k
	}
	r.left -= int64(n)
	return n, nil
}

func testData(t testing.TB, n int) []byte {
	t.Helper()
	b, err := io.ReadAll(newTestReader(int64(n)))
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// blockMap collects emitted blocks, copying them as emit requires.
type blockMap map[CID][]byte

func (m blockMap) put(c CID, b []byte) error {
	m[c] = bytes.Clone(b)
	return nil
}

func (m blockMap) get(_ context.Context, c CID) ([]byte, error) {
	b, ok := m[c]
	if !ok {
		return nil, fmt.Errorf("block %s not found", c)
	}
	return b, nil
}

// importAll imports data with opts and returns the root, size and blocks.
func importAll(t testing.TB, data []byte, opts Options) (CID, uint64, blockMap) {
	t.Helper()
	blocks := blockMap{}
	im, err := NewImporter(opts, blocks.put)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := im.Write(data); err != nil {
		t.Fatal(err)
	}
	root, size, err := im.Finish()
	if err != nil {
		t.Fatal(err)
	}
	return root, size, blocks
}
